    Sort sort = Sort.by(Sort.Direction.DESC, "age");
    Sort.Order order = sort.iterator().next();

    System.out.println("Sort 쪽:");
    System.out.println("  속성: " + order.getProperty()
            + " (" + order.getProperty().getClass().getSimpleName() + ")");
    System.out.println("  방향: " + order.getDirection());

    OrderSpecifier<?> spec = member.age.desc();
    System.out.println("Querydsl 쪽:");
    System.out.println("  대상: " + spec.getTarget()
            + " (" + spec.getTarget().getClass().getSimpleName() + ")");
    System.out.println("  방향: " + spec.getOrder());
}

