-- 허용 목록으로 잇는다

private OrderSpecifier<?>[] toOrders(Sort sort) {
    if (sort.isUnsorted()) {
        return new OrderSpecifier[]{ member.id.asc() };
    }
    return sort.stream()
            .map(o -> switch (o.getProperty()) {
                case "age"      -> o.isAscending()
                        ? member.age.asc() : member.age.desc();
                case "username" -> o.isAscending()
                        ? member.username.asc() : member.username.desc();
                case "teamName" -> o.isAscending()
                        ? team.name.asc() : team.name.desc();
                default         -> member.id.asc();
            })
            .toArray(OrderSpecifier[]::new);
}

