private OrderSpecifier<?>[] toOrdersGeneric(Sort sort) {
    PathBuilder<Member> path =
            new PathBuilder<>(Member.class, "member1");
    return sort.stream()
            .map(o -> new OrderSpecifier(
                    o.isAscending() ? Order.ASC : Order.DESC,
                    path.get(o.getProperty())))
            .toArray(OrderSpecifier[]::new);
}

